package ama.meeting;
import ama.contract.WorkspaceContracts.MeetingItem;import java.time.LocalDate;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PrototypeMeetingListFilterTest {
 MeetingItem row(){return new MeetingItem("00000000-0000-0000-0000-000000000001","产品复盘","BUSINESS",LocalDate.parse("2026-10-20"),"PUBLISHED","ACTIVE","OWNER","PUBLISHED_READ_ONLY","2","1",List.of("林晓芸"),"2026-10-29T10:00:00");}
 @Test void matchesActualMetadataAndConfirmedParticipants(){assertTrue(new MeetingListFilter("林晓",Set.of("PUBLISHED"),Set.of("BUSINESS"),LocalDate.parse("2026-10-01"),LocalDate.parse("2026-10-29")).matches(row()));assertFalse(new MeetingListFilter("产品",Set.of("ENTRY"),Set.of(),null,null).matches(row()));assertFalse(new MeetingListFilter("不存在",Set.of(),Set.of(),null,null).matches(row()));}
 @Test void workspaceStageIsIndependentOfLegacyRootStage(){var i=row();assertEquals("PUBLISHED",i.workspaceStage());assertEquals("MINUTES_PENDING",JdbcWebMeetingProjectionReader.workspaceStage("ENTRY",true,true,true,false));assertEquals("TRANSCRIPT_PENDING",JdbcWebMeetingProjectionReader.workspaceStage("ENTRY",true,false,false,false));assertEquals("READY_TO_PUBLISH",JdbcWebMeetingProjectionReader.workspaceStage("ENTRY",true,true,true,true));assertEquals("TRANSCRIPT_FAILED",JdbcWebMeetingProjectionReader.workspaceStage("TRANSCRIPT_FAILED",true,false,false,false));}
 @Test void canonicalCursorScopeSeparatesFiltersButNotSetOrdering(){var a=new MeetingListFilter("产品",Set.of("ENTRY","PUBLISHED"),Set.of("B","A"),null,null);var b=new MeetingListFilter("产品",new LinkedHashSet<>(List.of("PUBLISHED","ENTRY")),Set.of("A","B"),null,null);assertEquals(a.cursorKey(),b.cursorKey());assertNotEquals(a.cursorKey(),MeetingListFilter.NONE.cursorKey());assertNotEquals(a.cursorKey(),new MeetingListFilter("另一会议",a.stages(),a.categories(),null,null).cursorKey());}
 @Test void validCategoryFilterExcludesNormallyUncategorizedMeetings(){var i=row();var empty=new MeetingItem(i.id(),i.name(),null,null,"ENTRY",i.lifecycle(),i.relation(),i.writeState(),i.revisionToken(),i.accessRevisionToken());assertFalse(new MeetingListFilter("",Set.of(),Set.of("BUSINESS"),null,null).matches(empty));assertTrue(MeetingListFilter.NONE.matches(empty));assertTrue(new MeetingListFilter("",Set.of(),Set.of("BUSINESS"),null,null).matches(i));}
 @Test void rejectsInvalidFilterBeforeAnyRead(){assertThrows(IllegalArgumentException.class,()->new MeetingListFilter("x".repeat(129),Set.of(),Set.of(),null,null));assertThrows(IllegalArgumentException.class,()->new MeetingListFilter("",Set.of("UNKNOWN"),Set.of(),null,null));assertThrows(IllegalArgumentException.class,()->new MeetingListFilter("",Set.of(),Set.of(),LocalDate.parse("2026-11-01"),LocalDate.parse("2026-10-01")));}
}
